// New creates a Limiter with the given capacity, refill rate (tokens/sec),
// and clock. If clock is nil, the real clock is used.
func New(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, ErrInvalidCapacity
	}
	if rate <= 0 {
		return nil, errors.New("limiter: rate must be > 0")
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		tokens:   float64(capacity),
		capacity: float64(capacity),
		rate:     rate,
		clock:    clock,
	}, nil
}

// Allow reports whether one token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	if !l.last.IsZero() {
		elapsed := now.Sub(l.last).Seconds()
		if elapsed > 0 {
			l.tokens += elapsed * l.rate
			if l.tokens > l.capacity {
				l.tokens = l.capacity
			}
		}
	}
	l.last = now

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}
