// limiter.go
package limiter

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    int       // bucket capacity
	tokens   float64   // current tokens
	lastTime time.Time // last refill time
	clock    Clock
}

// New creates a Limiter with the given refill rate (tokens/sec) and burst
// capacity. The bucket starts full. If clock is nil, the real clock is used.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("limiter: rate must be positive")
	}
	if burst <= 0 {
		return nil, errors.New("limiter: burst must be positive")
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &Limiter{
		rate:     rate,
		burst:    burst,
		tokens:   float64(burst),
		lastTime: now,
		clock:    clock,
	}, nil
}

// Allow reports whether one token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, refilling based on elapsed
// time. It consumes the tokens atomically if available.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.lastTime).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.burst) {
			l.tokens = float64(l.burst)
		}
		l.lastTime = now
	}
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// RetryAfter returns the duration until n tokens would become available.
// It does not consume tokens.
func (l *Limiter) RetryAfter(n int) time.Duration {
	l.mu.Lock()
	defer l.mu.Unlock()

	if n < 0 {
		return -1
	}
	now := l.clock.Now()
	elapsed := now.Sub(l.lastTime).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.burst) {
			l.tokens = float64(l.burst)
		}
		l.lastTime = now
	}
	need := float64(n) - l.tokens
	if need <= 0 {
		return 0
	}
	return time.Duration(need / l.rate * float64(time.Second))
}
